const D = { scale:1, energy:.62, density:.55, speed:1, hue:190, x:.5, y:.5, style:'glass', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width,height), cx=width*P.x, cy=height*P.y, t=K.t, sty=P.style;
const en=P.energy;
const Rk = 2.4;
const sf = 0.108*u*P.scale;
const bass = Math.min(0.5, A.bass*0.6);
// two incommensurate tumble rates
const aX = t*(0.12+P.speed*0.10) + 0.30*Math.sin(t*0.051);
const aY = t*(0.088+P.speed*0.075) + 0.40*Math.sin(t*0.037+1.2);
const cX=Math.cos(aX), sX=Math.sin(aX), cY=Math.cos(aY), sY=Math.sin(aY);
const flow = t*(0.5+P.speed*0.7);

if (sty==='blueprint') background(215,60,15); else background(228,45,7);

function pt(uu,vv){
  const r = Rk + Math.cos(uu/2)*Math.sin(vv) - Math.sin(uu/2)*Math.sin(2*vv);
  let x = r*Math.cos(uu), y = r*Math.sin(uu), z = Math.sin(uu/2)*Math.sin(vv) + Math.cos(uu/2)*Math.sin(2*vv);
  // rot X
  let y1=y*cX - z*sX, z1=y*sX + z*cX;
  // rot Y
  let x2=x*cY + z1*sY, z2=-x*sY + z1*cY;
  return { x:cx+x2*sf, y:cy+y1*sf, z:z2 };
}
const TAU=Math.PI*2;
const Uf = Math.max(20, Math.min(40, Math.round(24 + P.density*18)));
const Vf = Uf;

// glass skin: additive translucent quads, brightness by depth (no sort needed w/ ADD)
if (sty!=='xray' && sty!=='blueprint'){
  blendMode(ADD); noStroke();
  const step=2;
  for (let i=0;i<Uf;i+=step){
    for (let j=0;j<Vf;j+=step){
      const a=pt(i/Uf*TAU, j/Vf*TAU), b=pt((i+step)/Uf*TAU, j/Vf*TAU), c=pt((i+step)/Uf*TAU,(j+step)/Vf*TAU), d=pt(i/Uf*TAU,(j+step)/Vf*TAU);
      const zz=(a.z+b.z+c.z+d.z)*0.25, lit=Math.max(0,Math.min(1,0.5+zz/5));
      const h = sty==='chrome' ? (P.hue+18*lit)%360 : (P.hue + 60*lit)%360;
      fill(h, sty==='chrome'?18:60, 22+50*lit + 10*bass, (7+8*en)*(P.alpha/100));
      beginShape(); vertex(a.x,a.y); vertex(b.x,b.y); vertex(c.x,c.y); vertex(d.x,d.y); endShape(CLOSE);
    }
  }
  blendMode(BLEND);
}

// wireframe u/v isolines, depth-cued, with a travelling bright band along u
const UL = Math.max(12, Math.min(22, Math.round(14 + P.density*8)));
const VL = UL;
noFill(); strokeCap(ROUND);
function polyU(uu){
  const band = 0.5+0.5*Math.sin(uu*2 - flow);
  let prev=null;
  for (let j=0;j<=Vf;j++){ const p=pt(uu, j/Vf*TAU); if(prev){ const lit=Math.max(0,Math.min(1,0.5+(p.z+prev.z)*0.5/5));
    if (sty==='blueprint'){ stroke(198,64,30+45*lit, (55+30*band)*(P.alpha/100)); strokeWeight(0.9+1.0*lit); }
    else { blendMode(ADD); stroke((P.hue+40*lit)%360, sty==='chrome'?20:55, 34+50*lit+18*band, (45+35*band+30*bass)*(P.alpha/100)); strokeWeight((0.8+1.6*lit)*(0.7+0.6*en)); }
    line(prev.x,prev.y,p.x,p.y); if(sty!=='blueprint') blendMode(BLEND);
  } prev=p; }
}
function polyV(vv){
  let prev=null;
  for (let i=0;i<=Uf;i++){ const p=pt(i/Uf*TAU, vv); if(prev){ const lit=Math.max(0,Math.min(1,0.5+(p.z+prev.z)*0.5/5));
    if (sty==='blueprint'){ stroke(206,50,26+40*lit, 40*(P.alpha/100)); strokeWeight(0.8+0.8*lit); }
    else { blendMode(ADD); stroke((P.hue+20+30*lit)%360, sty==='chrome'?14:45, 28+44*lit, (32+26*bass)*(P.alpha/100)); strokeWeight((0.7+1.2*lit)*(0.7+0.5*en)); }
    line(prev.x,prev.y,p.x,p.y); if(sty!=='blueprint') blendMode(BLEND);
  } prev=p; }
}
for (let a=0;a<UL;a++) polyU(a/UL*TAU);
for (let b=0;b<VL;b++) polyV(b/VL*TAU);

drawingContext.shadowBlur=0;
blendMode(BLEND);
